use super::{map_runtime_inputs, InputMappingError};
use std::error::Error;
use vb_core::{SlotIdx, SlotValue};
use vb_core::ids::{StepIdx, WorkflowDigest};
use vb_core::workflow::{CompiledWorkflow, CompiledNode, CompiledNodeKind, CompiledInputSlot, InputSlotKind, WorkflowParts, ResourceContract};
type TestResult<T> = Result<T, Box<dyn Error>>;
fn fixture(input_slots: Box<[CompiledInputSlot]>) -> TestResult<CompiledWorkflow> {
    let node = CompiledNode {
        id: StepIdx::ZERO, output: None, next: None, on_error: None, error_slot: None,
        kind: CompiledNodeKind::Finish { result: SlotIdx::new(2) },
    };
    let parts = WorkflowParts {
        name: Box::from("input-mapping"), digest: WorkflowDigest::from_bytes([1;32]),
        nodes: Box::from([node]), expressions: Box::from([]), accessors: Box::from([]),
        constants: Box::from([]), slot_count: 4, symbols_count: 0, entry: StepIdx::ZERO,
        resource_contract: ResourceContract::DEFAULT, step_names: Box::from([]), input_slots,
    };
    CompiledWorkflow::try_from_parts(parts).map_err(|error| error.to_string().into())
}
fn i64_port() -> CompiledInputSlot { CompiledInputSlot { slot: SlotIdx::new(2), kind: InputSlotKind::I64 } }
